widget.solution:
import numpy as np

def baseline_mse(y_train, y_test):
    y_train = np.asarray(y_train, dtype=float)
    y_test = np.asarray(y_test, dtype=float)
    guess = y_train.mean()
    return round(float(np.mean((y_test - guess) ** 2)), 6)
